"use client";

import { useState } from "react";
import Link from "next/link";
import { Category } from "../lib/api";
import { Menu, X } from "lucide-react";

type Props = {
  categories: Category[];
};

export default function NavbarClient({ categories }: Props) {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <>
      {/* tombol hamburger */}
      <button
        className="md:hidden p-2 text-gray-600"
        onClick={() => setIsOpen(!isOpen)}
        aria-label="Toggle menu"
      >
        {isOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

      {/* Mobile menu dropdown */}
      {isOpen && (
        <div
          className="md:hidden absolute top-16 left-0 right-0 bg-white 
                        border-t border-gray-100 shadow-lg z-50"
        >
          <nav className="flex flex-col px-4 py-3 gap-1">
            <Link
              href="/"
              onClick={() => setIsOpen(false)}
              className="py-2 text-gray-700 hover:text-blue-600 font-medium"
            >
              Beranda
            </Link>
            {categories.map((cat) => (
              <Link
                key={cat.id}
                href={`/kategori/${cat.slug}`}
                onClick={() => setIsOpen(false)}
                className="py-2 text-gray-600 hover:text-blue-600"
              >
                {cat.name}
              </Link>
            ))}
          </nav>
        </div>
      )}
    </>
  );
}
